<tr><td class="muted"><?= e(__('Imponibile / IVA / Totale')) ?></td><td><?= e(Alien\Core\Money::format((int)$inv['net'], $inv['currency'])) ?> / <?= e(Alien\Core\Money::format((int)$inv['vat'], $inv['currency'])) ?> / <strong><?= e(Alien\Core\Money::format((int)$inv['total'], $inv['currency'])) ?></strong></td></tr>
<tr><td class="muted"><?= e(__('File')) ?></td><td><code><?= e($inv['file_name']) ?></code></td></tr><?php if ($inv['sdi_id']): ?><tr><td class="muted"><?= e(__('Identificativo SdI')) ?></td><td><?= e($inv['sdi_id']) ?></td></tr><?php endif ?>
